import { PLAYER_OPTIONS_QUERY_PARAM } from '@/types/constants';

export function getQueryStringParamByName(name: string) {
  const playerOptionsValue = getRawPlayerOptions(window.location.search);
  let search = window.location.search;

  if (playerOptionsValue) {
    search = `?${playerOptionsValue}`;
  }

  const match = RegExp(`[?&]${name}=([^&]*)`).exec(search);
  return match && decodeURIComponent(match[1].replace(/\+/g, ' '));
}

const decodeURLParams = (search: string) => {
  const hashes = search.slice(search.indexOf('?') + 1).split('&');
  return hashes.reduce((params: any, hash: any) => {
    const split = hash.indexOf('=');

    if (split < 0) {
      return { ...params, [hash]: null };
    }

    const key = hash.slice(0, split);
    const val = hash.slice(split + 1);

    return { ...params, [key]: decodeURIComponent(val) };
  }, {});
};

function getRawPlayerOptions(search: string) {
  const searchParam = new URLSearchParams(search.slice(search.indexOf('?') + 1));
  const playerOptions = searchParam.get(PLAYER_OPTIONS_QUERY_PARAM);

  if (playerOptions) {
    const urlDecodedValue = decodeURIComponent(playerOptions);
    let decoded = atob(urlDecodedValue);

    // Handle legacy double-encoded URLs where first decode yields another player_options=<base64>
    const innerUrlParams = new URLSearchParams(decoded);
    const innerPlayerOptions = innerUrlParams.get(PLAYER_OPTIONS_QUERY_PARAM);

    if (innerPlayerOptions) {
      decoded = atob(decodeURIComponent(innerPlayerOptions));
    }
    return decoded;
  }

  return '';
}

export function extractPlayerOptions(search: string) {
  const playerOptionsValue = getRawPlayerOptions(search);

  if (playerOptionsValue) {
    return decodeURLParams(`?${playerOptionsValue}`);
  }

  return decodeURLParams(search);
}
