import SpeedIcon from '@/assets/speed-icon.svg';
import SubtitlesIcon from '@/assets/subtitles-icon.svg';
import SubtitlesIconActivated from '@/assets/subtitles-icon-activated.svg';
import VideoFailedIcon from '@/assets/video-failed-icon.png';
import VideoUnderProcessingIcon from '@/assets/video-under-processing-icon.png';
import VideoWasDeletedIcon from '@/assets/images/video_was_deleted.jpg';

export enum IconType {
  VideoFailed = 'videoFailed',
  VideoWasDeleted = 'videoWasDeleted',
  VideoUnderProcessing = 'videoUnderProcessing',
  PlaybackRate = 'playbackRate',
  Subtitles = 'subtitles',
  SubtitlesActivated = 'subtitlesActivated'
}

const iconMap = {
  [IconType.VideoFailed]: VideoFailedIcon,
  [IconType.VideoWasDeleted]: VideoWasDeletedIcon,
  [IconType.VideoUnderProcessing]: VideoUnderProcessingIcon,
  [IconType.PlaybackRate]: SpeedIcon,
  [IconType.Subtitles]: SubtitlesIcon,
  [IconType.SubtitlesActivated]: SubtitlesIconActivated
};

export const getIcon = (type: IconType, isOffline: boolean): string => {
  const basePath = isOffline ? '../player' : '';
  const icon = iconMap[type];
  return icon ? `${basePath}${icon}`: '';
};
