import { utils } from '@easygenerator/fragment-sdk';
import config from '@/config';
import { Statuses, defaultMedia, VIDEO_DEFAULT_TYPE, AUDIO_DEFAULT_TYPE } from '@/types/constants';
import { isCdnUrl } from '@/utils/utils';
import { MediaInfoConfig, MediaFileInfo, MediaType } from '@/types/media';

const HttpWrapper = utils.HttpWrapper;
export class MediaService {
  static async getMediaFileInfo(mediaConfig: MediaInfoConfig): Promise<MediaFileInfo> {
    const { isVideo, source, thumbnail, courseId, publishMode, isOffline = false } = mediaConfig;

    if (isOffline) {
      return this.getMediaInfoLocally(source, isVideo);
    }

    if (!source || isCdnUrl(source)) {
      return this.getDefaultMediaInfo(isVideo, source, thumbnail);
    }

    return this.getMediaInfoFromMediaService(isVideo, source, courseId, publishMode);
  }

  private static async getMediaInfoFromMediaService(
    isVideo: boolean,
    sourceId: string,
    courseId?: string,
    publishMode?: string
  ) {
    try {
      const mediaType = isVideo ? MediaType.Video : MediaType.Audio;
      const url = this.injectMediaMetadata(
        `${config.mediaServiceUrl}/api/media/${mediaType}/info/${sourceId}`,
        courseId,
        publishMode
      );
      return await HttpWrapper.get(url, { fetchOptions: { credentials: 'include' } });
    } catch (err) {
      return { status: Statuses.NotFound };
    }
  }

  private static async getDefaultMediaInfo(
    isVideo: boolean,
    sourceUrl?: string,
    thumbnail = defaultMedia.video.thumbnail
  ) {
    let defaultMediaInfo = isVideo ? defaultMedia.video : defaultMedia.audio;

    if (sourceUrl) {
      defaultMediaInfo = {
        sources: [
          {
            src: sourceUrl,
            type: isVideo ? VIDEO_DEFAULT_TYPE : AUDIO_DEFAULT_TYPE
          }
        ],
        ...(isVideo && { thumbnail })
      };
    }

    return { ...defaultMediaInfo, status: Statuses.Available };
  }

  private static async getMediaInfoLocally(sourceId: string, isVideo: boolean) {
    try {
      const mediaInfo = await HttpWrapper.get(`../media/${sourceId}.json`);
      return {
        ...mediaInfo,
        sources: [
          {
            src: mediaInfo.sourceUrl,
            type: isVideo ? VIDEO_DEFAULT_TYPE : AUDIO_DEFAULT_TYPE
          }
        ],
        status: Statuses.Available
      };
    } catch (err) {
      return { status: Statuses.NotFound };
    }
  }

  private static injectMediaMetadata(url: string, courseId?: string, publishMode?: string): string {
    if (!(courseId && publishMode)) {
      return url;
    }
    return `${url}?courseId=${courseId}&publishMode=${publishMode}`;
  }
}
