import styled from 'vue-styled-components';
import { themeColors } from '@/types/constants';
import { IconType, getIcon } from '@/utils/icons';

const options = { colors: Object, status: String, isVideo: Boolean, isOffline: Boolean };
const { contentBodyColor, textColor } = themeColors;


const StatusMessage = styled('div', options)`
  display: flex;
  flex-direction: column;
  gap: 20px;

  &.container {
    width: 100%;
    height: 100%;
    display: flex;
    align-items: center;
    justify-content: center;
    background-size: 100% 100%;
    background-position: center;
    background-repeat: no-repeat;
    background-color: ${props => props.colors[contentBodyColor]};
    color: ${props => props.colors[textColor]};
    font-size: 16px;
  }

  &.background {
    &.video {
      &.conversion-failed,
      &.not-supported,
      &.uploading,
      &.converting,
      &.loaded,
      &.failed {
        display: flex;
        flex-direction: column;
        justify-content: center;
        text-align: center;
        background: #f4f8fb;

        &.converting,
        &.loaded {
          background: #ffffff;
        }

        .icon {
          width: 80px;
          height: 80px;
          margin: 20px auto 16px;
        }
        p {
          font: normal 24px 'Qanelas-Soft', sans-serif;
          color: #8296a8;

          &.processing {
            color: var(--General-500, #9B9FA6);
            font: normal 600 14px/1.3 "Qanelas-Soft",sans-serif;
            margin: 0;
          }
        }
      }
      &.failed,
      &.conversion-failed,
      &.not-supported {
        .icon {
          background: url(${props => getIcon(IconType.VideoFailed, props.isOffline)}) center no-repeat;
          background-size: 100% 100%;
        }
      }
      &.uploading,
      &.loaded {
        .icon {
          background: url(${props => getIcon(IconType.VideoUnderProcessing, props.isOffline)}) center no-repeat;
          background-size: 100% 100%;
        }
      }
      &.not-found {
        background: url(${props => getIcon(IconType.VideoWasDeleted, props.isOffline)}) center no-repeat;
        background-size: 100% 100%;
      }
      
    }
    &.not-supported {
      background: url(~@/assets/images/audio_not_supported.jpg) center no-repeat;
      background-size: 100% 100%;
    }
    &.conversion-failed {
      background: url(~@/assets/images/audio_error.jpg) center no-repeat;
      background-size: 100% 100%;
    }
    &.uploading,
    &.converting {
      background: url(~@/assets/images/audio_processing.jpg) center no-repeat;
      background-size: 100% 100%;
    }
    &.not-found {
      background: url(~@/assets/images/audio_was_deleted.jpg) center no-repeat;
      background-size: 100% 100%;
    }
  }
`;

export default StatusMessage;
