import styled from 'vue-styled-components';
import { commonStyles, controlBar } from './Video';
import { themeColors } from '../../types/constants';
import SpeedIcon from '@/assets/speed-icon.svg';

const themeStyles = { colors: Object };
const { contentBodyColor, mainColor, textColor } = themeColors;

const Audio = styled('audio', themeStyles)`
  &.audio-player {
    ${props => commonStyles(props)}

    &.video-js {
      background-color: transparent;
      color: ${props => props.colors[mainColor]};

      ${props =>
        controlBar(
          props,
          `
            display: flex;
            opacity: 1;
            
            .vjs-play-control {
              margin-right: 0;
            }

            .vjs-progress-control {
              padding: 0 12px;
              
              .vjs-progress-holder {
                .vjs-load-progress {
                  background-color: transparent;

                  div {
                    background-color: transparent;
                  }
                }
              }
            }
          `
        )}
      &.vjs-has-started {
        &.vjs-user-inactive {
          &.vjs-playing {
            .vjs-control-bar {
              visibility: visible;
              opacity: 1;
            }
          }
        }
      }

      .vjs-big-play-button {
        display: none;
      }

      .vjs-tech {
        width: 0;
        height: 0;
        position: absolute;
        top: -100px;
        left: -100px;
        visibility: hidden;
      }

      &.vjs-seeking,
      &.vjs-waiting {
        .vjs-loading-spinner {
          display: none;
        }
      }

      .vjs-control-bar {
        ${props => audioPlaybackRate(props.colors)}

        .vjs-remaining-time {
          padding: 0 6px 0 0;
        }

        .vjs-mute-control {
          margin: 0;
          order: 0;
          width: 28px;

          span:before {
            font-size: 16px;
          }
        }

        .vjs-volume-control {
          right: 28px;
          left: auto;

          @media (max-width: 400px) {
            right: 10px;
          }
        }
      }
    }
  }
`;

export const audioPlaybackRate = colors => `

  .vjs-menu-button:focus-within .vjs-menu,
  .vjs-menu:focus-within {
    display: block !important;
    visibility: visible;
    opacity: 1;
    pointer-events: auto;
  }

  .vjs-audio-playback-rate {
     margin-right: 26px;
     width: 28px;
     
     @media (max-width: 400px) {
        margin-right: 17px !important;
     }

     @media (max-width: 200px) {
        margin-right: 6px !important;
     }

    .vjs-menu {
      width: 91px;
      left: auto;
      right: -26px;
      -webkit-tap-highlight-color: rgba(0, 0, 0, 0);

      @media (max-width: 400px) {
        right: -17px;
      }
      
      @media (max-width: 200px) {
        right: -6px;
      }
      
      .vjs-menu-content {
        cursor: default;
        background: #fff;
        box-shadow: 0px 1px 4px 0px rgba(0, 0, 0, 0.10);
      }
    }
    
    .vjs-audio-playback-rate-wrapper {
      margin: 8px;
      padding: 0;
      height: 16px;
      display: flex;
      justify-content: space-between;
      font-family: 'Qanelas-Soft', 'Avenir', Helvetica, Arial, sans-serif;
      
      > span {
        flex: 1;
      }
      
      button {
        width: 16px;
        height: 16px;
        border-radius: 50%;
        background: #F5F5F6;
        cursor: pointer;
        position: relative;
        padding: 0;
        
        &:before {
          content: '';
          display: block;
          position: absolute;
          width: 6px;
          height: 2px;
          background: #9B9FA6;
          top: 50%;
          left: 50%;
          transform: translate3D(-50%, -50%, 0);
        }
        
        &[disabled] {
          cursor: no-drop;
        }

        &[disabled]:before, &[disabled].plus:after {
          background: #D7D8DC;
        }

        &:not([disabled]):hover {
          background: #EBECED;

          &:before, &.plus:after {
            background: #363E4E;
          }
        }

        &.plus:after {
          content: '';
          display: block;
          position: absolute;
          width: 2px;
          height: 6px;
          background: #9B9FA6;
          top: 50%;
          left: 50%;
          transform: translate3D(-50%, -50%, 0);
        }
      }

      strong {
        color: #363E4E;
        font-size: 10px;
        line-height: 13px;
      }

      .value {
        color: #363E4E;
        font-size: 12px;
        line-height: 15.6px;
      }
    }

    .vjs-playback-rate-value {
      display: none;
    }

    button {
      &:not(.vjs-disabled):hover {
        .vjs-icon-placeholder:before {
          background-color: ${colors[mainColor]};
        }
      }

      &.active {
        .vjs-icon-placeholder:before {
          background-color: ${colors[mainColor]};
        }
      }
    }

    .vjs-icon-placeholder {
      position: relative;

      &:before {
        content: '';
        display: block;
        background-color: ${colors[textColor]};
        mask: url(${SpeedIcon}) no-repeat 50% 50%;

        width: 16px;
        height: 16px;
        position: absolute;
        left: 50%;
        top: 50%;
        transform: translate3d(-50%, -50%, 0);
      }
    }
  }
`;

export default Audio;
