import { MEDIA_RESTRICTION_POST_MESSAGES } from '@/types/constants';
import StorageHelper from '@/utils/storageHelper';
import { sendPostMessage } from '@/utils/utils';

export class MediaProgressManager {
  private readonly mediaId: string;
  private readonly attemptId: string;
  private readonly questionId: string;
  private readonly isReviewOrPreviewMode: boolean;
  private readonly parentOrigin: string;
  private readonly isVideo: boolean;

  constructor(
    questionId: string,
    mediaId: string,
    attemptId: string,
    isReviewOrPreviewMode: boolean,
    parentOrigin: string,
    isVideo: boolean
  ) {
    this.mediaId = mediaId;
    this.attemptId = attemptId;
    this.questionId = questionId;
    this.isReviewOrPreviewMode = isReviewOrPreviewMode;
    this.parentOrigin = parentOrigin;
    this.isVideo = isVideo;
  }

  saveProgress(progressedTime: number): void {
    this.saveProgressToLocal(progressedTime);
    this.sendProgressToParent(progressedTime);
  }

  saveProgressToLocal(progressedTime: number): void {
    if (this.isReviewOrPreviewMode) {
      sessionStorage.setItem(`${this.questionId}_${this.mediaId}`, `${progressedTime}`);
      return;
    }

    StorageHelper.set(`${this.attemptId}_${this.mediaId}`, progressedTime);
  }

  sendProgressToParent(progressedTime: number): void {
    if (this.isReviewOrPreviewMode) {
      return;
    }

    sendPostMessage(
      window.parent,
      {
        type: MEDIA_RESTRICTION_POST_MESSAGES.SET_PROGRESS,
        value: {
          ...(this.isVideo ? { videoId: this.mediaId } : { audioId: this.mediaId }),
          progressedTime,
          questionId: this.questionId
        }
      },
      this.parentOrigin
    );
  }

  requestProgressFromParent(): void {
    if (this.isReviewOrPreviewMode) {
      return;
    }

    sendPostMessage(
      window.parent,
      {
        type: MEDIA_RESTRICTION_POST_MESSAGES.GET_PROGRESS,
        value: {
          ...(this.isVideo ? { videoId: this.mediaId } : { audioId: this.mediaId }),
          questionId: this.questionId
        }
      },
      this.parentOrigin
    );
  }

  notifyCompletionToParent(): void {
    sendPostMessage(
      window.parent,
      {
        type: this.isVideo
          ? MEDIA_RESTRICTION_POST_MESSAGES.VIDEO_COMPLETED
          : MEDIA_RESTRICTION_POST_MESSAGES.AUDIO_COMPLETED,
        value: {
          ...(this.isVideo ? { videoId: this.mediaId } : { audioId: this.mediaId }),
          questionId: this.questionId
        }
      },
      this.parentOrigin
    );
  }

  getLocalProgress(): number {
    if (this.isReviewOrPreviewMode) {
      return +sessionStorage.getItem(`${this.questionId}_${this.mediaId}`) | 0;
    }
    return +StorageHelper.get(`${this.attemptId}_${this.mediaId}`) | 0;
  }
}
