import videojs from 'video.js';
import 'video.js/dist/video-js.min.css';
import 'videojs-hotkeys';
import * as qualitySelector from '@silvermine/videojs-quality-selector';
import '@silvermine/videojs-quality-selector/dist/css/quality-selector.css';
import {
  IAudioPlaybackMenuItemOptions,
  IAudioPlaybackRateButtonOptions,
  IMenuButton,
  ISubtitles,
  ITooltip,
  IVideoSource
} from '@/types/types';
import {
  playerTranslation,
  subtitlesKey,
  volumeKey,
  LANGUAGE_LABEL_MAX_LENGTH,
  SUPPORTED_PLAYBACK_RATES,
  AUDIO_CURRENT_PLAYBACK_RATE_HTML_ID,
  RATE_NORMAL,
  AUDIO_PLAYBACK_RATE_BUTTON_NAME,
  MEDIA_DECODE_ERROR_CODE
} from '@/types/constants';
import { IPlayerOptions, playerDefaultOptions } from '@/types/playerOptions';
import { getNameByLangCode, numerate } from '@/utils/utils';
import StorageHelper from '@/utils/storageHelper';
import toBoolean from '@/utils/toBoolean';
import { MediaRestriction } from './media-restriction';
import clientConfig from '@/config';

qualitySelector(videojs);
// "videojs-hls-quality-selector": "^1.1.1" as alternative (works only with hls files)

export default class VJSPlayer {
  public defaultOptions: IPlayerOptions;
  public controlBarOptions: IPlayerOptions['controlBar'];
  public shouldRerender: boolean = false;
  private player: any = null;
  private subtitles: ISubtitles[] = [];
  private queryStringLang: string = '';
  private preferredSubtitleLang: string = '';
  private selectedSubtitlesLanguage: string | null = null;
  private updateSubtitlesViaClickPlayButton = false;
  private readonly mediaRestriction: MediaRestriction;

  constructor(spec: any, translator: () => void) {
    videojs.addLanguage('custom', playerTranslation(translator));

    const config = { ...playerDefaultOptions, ...spec };
    const videoControlBarOptions = {
      audioTrackButton: false,
      playToggle: toBoolean(config.play_toggle),
      volumeMenuButton: toBoolean(config.volume_menu_button),
      currentTimeDisplay: toBoolean(config.current_time_display),
      timeDivider: toBoolean(config.time_divider),
      durationDisplay: toBoolean(config.duration_display),
      progressControl: toBoolean(config.progress_control),
      liveDisplay: toBoolean(config.live_display),
      remainingTimeDisplay: toBoolean(config.remaining_time_display),
      customControlSpacer: toBoolean(config.custom_control_spacer),
      pictureInPictureToggle: toBoolean(config.picture_in_picture_toggle),
      chaptersButton: toBoolean(config.chapters_button),
      muteToggle: toBoolean(config.mute_toggle),
      volumeControl: toBoolean(config.volume_control),
      volumePanel: toBoolean(config.volume_panel),
      subtitlesButton: toBoolean(config.subtitles_button),
      playbackRateMenuButton: toBoolean(config.video),
      qualitySelector: toBoolean(config.video),
      fullscreenToggle: toBoolean(config.fullscreen_toggle)
    };

    const audioControlBarOptions = {
      playToggle: toBoolean(config.play_toggle),
      currentTimeDisplay: toBoolean(config.current_time_display),
      durationDisplay: toBoolean(config.duration_display),
      progressControl: toBoolean(config.progress_control),
      remainingTimeDisplay: toBoolean(config.remaining_time_display),
      muteToggle: toBoolean(config.mute_toggle),
      volumeMenuButton: toBoolean(config.volume_menu_button),
      volumeControl: toBoolean(config.volume_control)
    };

    this.controlBarOptions = config.video ? videoControlBarOptions : audioControlBarOptions;

    this.defaultOptions = {
      controls: config.controls,
      preload: config.preload,
      language: config.language,
      source: config.source,
      autoplay: toBoolean(config.autoplay),
      video: toBoolean(config.video),
      loop: toBoolean(config.loop),
      css: config.css,
      background: toBoolean(config.background) || toBoolean(config.video),
      styleVariables: JSON.parse(config.style_variables),
      fontSize: config.font_size,
      poster: config.poster,
      controlBar: this.sortControlBar(),
      textTrackSettings: config.text_track_settings,
      plugins: {},
      sources: [],
      html5: {
        // if set to false, subtitles won't show on iphone in fullscreen
        // this is a limitation,  https://github.com/videojs/video.js/issues/8061
        nativeTextTracks: this.isIos() && this.isIphone()
      },
      restricted: toBoolean(config.restricted),
      isReviewOrPreviewMode: toBoolean(config.isReviewOrPreviewMode),
      isRtl: toBoolean(config.isRtl),
      videoId: config.videoId,
      questionId: config.questionId,
      attemptId: config.attemptId,
      compactTooltip: toBoolean(config.compactTooltip)
    };

    if (this.defaultOptions.restricted) {
      this.mediaRestriction = new MediaRestriction({
        isReviewOrPreviewMode: this.defaultOptions.isReviewOrPreviewMode,
        mediaId: window.name,
        questionId: this.defaultOptions.questionId,
        attemptId: this.defaultOptions.attemptId,
        isRtl: this.defaultOptions.isRtl,
        isVideo: this.defaultOptions.video,
        compactTooltip: this.defaultOptions.compactTooltip
      });
      this.options.disablePictureInPicture = true;
    }
  }

  public initialize(reference: HTMLFormElement, tooltipReference: Vue & ITooltip) {
    if (this.isIosOrAndroid()) {
      this.options.controlBar.volumeControl = false;
    }
    if (!this.options.video || (this.isIos() && this.defaultOptions.restricted)) {
      // disable full screen mode on mobile as on full screen native video player is used and restriction doesn't work
      this.options.controlBar.fullscreenToggle = false;
    }

    this.options.playbackRates = SUPPORTED_PLAYBACK_RATES;

    this.player = videojs(reference, this.options, () => {
      this.patchCurrentSources();
      this.setInitialVolumeSettings();
      this.initPlugins();
      this.setupEvents();
      this.overrideAriaLive();
      this.configureAttributes();

      if (this.options.video) {
        this.initSubtitles();
        this.initQualitySelector();
        this.initVideoPlaybackRate();
      } else {
        this.initAudioPlaybackRate();
      }
      
      if (this.isIos() || this.isIphone()) {
        const iframeParentUrl = clientConfig.parentOrigin;
        this.player.one('canplay', () => {
          window.parent.postMessage('PLAYER_READY', iframeParentUrl);
        });
      }
    });

    this.applySources();

    if (this.mediaRestriction) {
      this.mediaRestriction
        .initialize(this.player, {
          tooltipReference,
          sourceTypes: [...new Set<string>(this.options.sources.map(({ type }) => type))]
        })
        .apply();

      this.setupProgressControlScreenReader();
    }
  }

  applySources() {
    if (this.player) {
      this.player.src([...this.options.sources]);
    }
  }

  public setSources(sources: any[]) {
    this.options.sources = this.setSourceLabels(sources as IVideoSource[]);
    this.options.sources = this.sortSources(sources as IVideoSource[]);
    if (this.player) {
      this.player.src(this.options.sources);
    }
  }

  public setPoster(poster: string) {
    this.options.poster = poster;
    if (this.player) {
      this.player.setPoster(this.options.poster);
    }
  }

  public setSubtitles(subtitles: ISubtitles[]) {
    this.subtitles = subtitles;
  }

  public setQueryStringLang(lang: string) {
    this.queryStringLang = lang;
  }

  public setPreferredSubtitleLang(lang: string) {
    this.preferredSubtitleLang = lang;
  }

  public dispose() {
    if (this.player) {
      const trackList = this.player.textTracks();
      trackList.removeEventListener('change');

      document.removeEventListener('click', this.handleAudioPlaybackRateOutsideClick);
      window.removeEventListener('blur', this.handleAudioPlaybackRateBlur);

      this.player.dispose();
    }
  }

  private readonly setupProgressControlScreenReader = (): void => {
    const progressControl = this.player.controlBar.progressControl.el();

    progressControl.setAttribute('aria-describedby', 'tooltip-container');
    progressControl.setAttribute('role', 'progressbar');
  };

  private configureAttributes(): void {
    const videoElement = document.querySelector('.vjs-tech');
    videoElement.setAttribute('playsinline', '');
    videoElement.setAttribute('controlslist', 'nofullscreen');
  }

  private sortControlBar() {
    return {
      children: Object.keys(this.controlBarOptions)
        .map(key => this.controlBarOptions[key] && key)
        .filter(i => i)
    };
  }

  get options(): any {
    return this.defaultOptions;
  }

  set options(options) {
    this.defaultOptions = { ...this.defaultOptions, ...options };
  }

  private setupEvents() {
    if (!this.player) {
      return;
    }

    this.player.on('error', () => {
      const { code } = this.player.error();
      // Check for a specific media decode error and attempt to re-render for issues related to chromimum browser
      if (code === MEDIA_DECODE_ERROR_CODE) {
        // Clear the current error and set flag to re-render
        this.player.error(null);
        this.shouldRerender = true;
      }
    });
    this.player.on('play', () => {
      this.onPlay();
    });

    this.player.on('volumechange', () => {
      this.onVolumeChange();
    });

    this.player.on(qualitySelector.EVENTS.QUALITY_REQUESTED, () => {
      this.addSubtitlesToPlayer();
      this.disableSubtitlesIfEmpty();
    });

    if (this.isIosOrAndroid() && this.player.controlBar.progressControl.seekBar.mouseTimeDisplay) {
      this.player.controlBar.progressControl.seekBar.mouseTimeDisplay.hide();
    }
  }

  get isSelectedSubtitles() {
    const { language } = StorageHelper.get(subtitlesKey);
    return this.subtitles.some(sub => sub.languageCode === language);
  }

  private isDefaultSubtitles(languageCode: string) {
    const { language, subtitlesOff } = StorageHelper.get(subtitlesKey);

    if (subtitlesOff) {
      return false;
    }

    if (this.preferredSubtitleLang && this.preferredSubtitleLang === languageCode) {
      return true;
    }

    if (language) {
      return language === languageCode;
    }

    return this.queryStringLang && this.queryStringLang === languageCode;
  }

  private initSubtitles() {
    this.addSubtitlesToPlayer();

    const trackList = this.player.textTracks();
    trackList.addEventListener('change', this.onChangeSubtitles.bind(this));

    const SubtitlesMenuButton = this.getSubtitlesMenuButton();
    SubtitlesMenuButton.off('mouseenter');

    if (this.isSelectedSubtitles) {
      SubtitlesMenuButton.el().classList.add('active');
    }

    this.disableSubtitlesIfEmpty();

    this.createSubtitlesNotificationElement();

    setTimeout(this.setTitleForSubtitlesMenuItem, 1);
  }

  private addSubtitlesToPlayer() {
    const addSuffix = numerate();

    let targetSubtitlesLang: string | undefined;

    if (this.preferredSubtitleLang && this.subtitles.some(sub => sub.languageCode === this.preferredSubtitleLang)) {
      targetSubtitlesLang = this.preferredSubtitleLang;
    } else if (this.queryStringLang && this.subtitles.some(sub => sub.languageCode === this.queryStringLang)) {
      targetSubtitlesLang = this.queryStringLang;
    }

    if (targetSubtitlesLang) {
      this.subtitles.sort((a, b) => {
        if (a.languageCode === targetSubtitlesLang) {
          return -1;
        } else if (b.languageCode === targetSubtitlesLang) {
          return 1
        }
        return 0;
      });
    }

    this.subtitles.forEach(sub =>
      this.player.addRemoteTextTrack({
        kind: 'subtitles',
        srclang: sub.languageCode,
        label: addSuffix(getNameByLangCode(sub.languageCode)),
        src: sub.filePath,
        default: this.isDefaultSubtitles(sub.languageCode)
      })
    );

    if (targetSubtitlesLang) {
      const matchedSubtitle = this.subtitles.find(sub => sub.languageCode === targetSubtitlesLang);
      this.selectedSubtitlesLanguage = matchedSubtitle.languageCode;
    } else if (StorageHelper.existsKey(subtitlesKey)) {
      const { language } = StorageHelper.get(subtitlesKey);

      this.selectedSubtitlesLanguage = language; // undefined -> Subtitles OFF
    } else {
      this.selectedSubtitlesLanguage = this.queryStringLang;
    }
  }

  private disableSubtitlesIfEmpty() {
    const SubtitlesMenuButton = this.getSubtitlesMenuButton();
    if (!this.subtitles.length) {
      SubtitlesMenuButton.disable();
      SubtitlesMenuButton.off('tap');
      SubtitlesMenuButton.controlText('Subtitles/captions not available');
      // fake subtitles
      this.player.addRemoteTextTrack({
        kind: 'subtitles',
        label: 'label',
        default: false
      });
    }
  }

  private setTitleForSubtitlesMenuItem() {
    const selector = '.vjs-subtitles-button ul li';
    const menuItemList = document.querySelectorAll(selector);

    for (const menuItem of menuItemList) {
      const languageLabel = menuItem.querySelector('.vjs-menu-item-text').textContent;
      if (languageLabel && languageLabel.length > LANGUAGE_LABEL_MAX_LENGTH) {
        menuItem.setAttribute('title', languageLabel);
      }
    }
  }

  private createSubtitlesNotificationElement() {
    const textTrackSelector = '.vjs-text-track-display';
    const textTrackElement = document.querySelector(textTrackSelector);

    const subtitlesNotificationElement = document.createElement('div');
    subtitlesNotificationElement.classList.add('subtitles-notification');

    textTrackElement.parentElement.insertBefore(subtitlesNotificationElement, null);
  }

  private patchCurrentSources() {
    const originalCurrentSources = this.player.currentSources.bind(this.player);
    this.player.currentSources = () => {
      const sources = originalCurrentSources();
      if (sources.length === 1 && sources[0] && sources[0].src && sources[0].src.startsWith('blob:')) {
        return this.options.sources;
      }
      return sources;
    };
  }

  private initQualitySelector() {
    this.player.controlBar.getChild('QualitySelector').getChild('QualitySelector').off('mouseenter');
  }

  private setInitialVolumeSettings() {
    if (!StorageHelper.exists() || !this.player) {
      return;
    }

    const volumeSettings = StorageHelper.get(volumeKey);
    if (volumeSettings) {
      this.player.volume(volumeSettings.volume);
      this.player.muted(volumeSettings.muted);
    }
  }

  private initPlugins() {
    this.player.hotkeys({ enableInactiveFocus: false, enableVolumeScroll: false });
  }

  private overrideAriaLive() {
    const playToggleElem = this.player.controlBar.playToggle.el_;
    const ariaLiveElem = playToggleElem.querySelector('[aria-live="polite"]');

    const observer = new MutationObserver(() => {
      if (document.activeElement !== playToggleElem) {
        ariaLiveElem.innerHTML = '';
      }
    });

    observer.observe(ariaLiveElem, { childList: true });
  }

  private onVolumeChange() {
    let volume: number = this.player.volume();
    let muted: boolean = this.player.muted();
    if (volume === 0) {
      volume = 1;
      muted = true;
      const volumeSettings = StorageHelper.get(volumeKey);
      if (volumeSettings && volumeSettings.volume) {
        volume = volumeSettings.volume;
      }
    }
    StorageHelper.set(volumeKey, { volume, muted });
  }

  private onPlay() {
    const volumeSettings = StorageHelper.get(volumeKey);
    const { language, subtitlesOff } = StorageHelper.get(subtitlesKey);

    if (this.mediaRestriction) {
      this.mediaRestriction.onPlay();
    }

    if (volumeSettings) {
      this.player.volume(volumeSettings.volume);
      this.player.muted(volumeSettings.muted);
    }

    if (
      (language && language !== this.selectedSubtitlesLanguage) ||
      (subtitlesOff && !!this.selectedSubtitlesLanguage)
    ) {
      this.updateSubtitlesMode(language);
    }
  }

  private async updateSubtitlesMode(language: string | undefined) {
    const tracks = this.player.textTracks().tracks_;
    let selected = false;

    for (const element of tracks) {
      element.mode = 'disabled';

      if (element.language === language) {
        element.mode = 'showing';
        selected = true;
      }
    }

    if (selected) {
      await this.setSubtitlesOn(language);
    } else {
      await this.setSubtitlesOff();
    }

    this.updateSubtitlesViaClickPlayButton = true;
  }

  private setSourceLabels(sources: IVideoSource[] = []) {
    return [...sources].map((source: IVideoSource) => {
      if (source && source.height) {
        source.label = `${source.height}p`;
      } else if (source) {
        source.label = 'Auto';
        source.selected = true;
      }
      return source;
    });
  }

  private sortSources(sources: IVideoSource[] = []) {
    return this.sortSourcesByType(this.sortSourcesByQuality(sources));
  }

  private sortSourcesByQuality(sources: IVideoSource[] = []) {
    return [...sources].sort((a: IVideoSource, b: IVideoSource) => b.height - a.height);
  }

  private sortSourcesByType(sources: any[] = []) {
    return [...sources].sort((a: IVideoSource, b: IVideoSource) => b.type.localeCompare(a.type));
  }

  private isIosOrAndroid() {
    return videojs.browser.IS_ANDROID || this.isIos();
  }

  private isIos() {
    return videojs.browser.IS_IOS || (videojs.browser.IS_SAFARI && videojs.browser.TOUCH_ENABLED);
  }

  private isIphone() {
    return videojs.browser.IS_IPHONE;
  }

  private async onChangeSubtitles() {
    if (!this.updateSubtitlesViaClickPlayButton) {
      const tracks = this.player.textTracks().tracks_;
      let areSubtitlesOff = true;

      for (const track of tracks) {
        const { kind, mode, language } = track;

        if (kind === 'subtitles' && mode === 'showing') {
          areSubtitlesOff = false;
          await this.setSubtitlesOn(language);
          StorageHelper.set(subtitlesKey, { language });
        }
      }

      if (areSubtitlesOff) {
        await this.setSubtitlesOff();
        StorageHelper.set(subtitlesKey, { subtitlesOff: true });
      }
    }
    this.updateSubtitlesViaClickPlayButton = false;
  }

  private getSubtitlesMenuButton() {
    return this.player.controlBar.getChild('SubtitlesButton').getChild('SubtitlesButton');
  }

  private async setSubtitlesOn(language: string) {
    const SubtitlesMenuButton = this.getSubtitlesMenuButton();

    SubtitlesMenuButton.el().classList.add('active');
    this.selectedSubtitlesLanguage = language;
    await this.showSubtitleNotification('Subtitles are ON');
  }

  private async setSubtitlesOff() {
    const SubtitlesMenuButton = this.getSubtitlesMenuButton();

    SubtitlesMenuButton.el().classList.remove('active');
    this.selectedSubtitlesLanguage = null;
    await this.showSubtitleNotification('Subtitles are OFF');
  }

  private async showSubtitleNotification(text: string) {
    const subtitlesSelector = '.subtitles-notification';
    const subtitlesNotificationElement = document.querySelector(subtitlesSelector);

    if (subtitlesNotificationElement) {
      subtitlesNotificationElement.classList.remove('show');
      subtitlesNotificationElement.textContent = text;

      await new Promise(resolve => {
        window.requestAnimationFrame(resolve);
      });
      subtitlesNotificationElement.classList.add('show');
    }
  }

  private initVideoPlaybackRate() {
    const PlaybackRateMenuButton = this.player.controlBar.getChild('PlaybackRateMenuButton');

    const MenuButton = PlaybackRateMenuButton.getChild('PlaybackRateMenuButton');
    this.player.on('ratechange', () => {
      if (this.player.playbackRate() !== RATE_NORMAL) {
        MenuButton.el().classList.add('active');
      } else {
        MenuButton.el().classList.remove('active');
      }
    });
    MenuButton.off('mouseenter');
    MenuButton.controlText('Video speed');
    PlaybackRateMenuButton.el()
      .querySelectorAll('.vjs-menu-item-text')
      .forEach(x => (x.innerText = x.innerText.slice(0, -1)));
  }

  private initAudioPlaybackRate() {
    const Component = videojs.getComponent('Component');
    const MenuButtonComponent = videojs.getComponent('MenuButton');

    const AudioPlaybackRateButton = new MenuButtonComponent(this.player, {
      className: 'vjs-audio-playback-rate',
      name: AUDIO_PLAYBACK_RATE_BUTTON_NAME,
      controlText: 'Audio speed'
    } as IAudioPlaybackRateButtonOptions) as IMenuButton;

    const buttonMinusElement = document.createElement('button');
    buttonMinusElement.classList.add('minus');
    buttonMinusElement.onclick = () => {
      const currentPlaybackRate = this.player.playbackRate();
      const currentIndex = this.options.playbackRates.findIndex((i: number) => i === currentPlaybackRate);

      this.player.playbackRate(this.options.playbackRates[currentIndex - 1]);
      if (currentIndex - 1 === 0) {
        buttonMinusElement.disabled = true;
      }

      buttonPlusElement.disabled = false;
    };

    const buttonPlusElement = document.createElement('button');
    buttonPlusElement.classList.add('plus');
    buttonPlusElement.onclick = () => {
      const currentPlaybackRate = this.player.playbackRate();
      const currentIndex = this.options.playbackRates.findIndex((i: number) => i === currentPlaybackRate);

      this.player.playbackRate(this.options.playbackRates[currentIndex + 1]);
      if (currentIndex + 1 === this.options.playbackRates.length - 1) {
        buttonPlusElement.disabled = true;
      }

      buttonMinusElement.disabled = false;
    };

    const currentValueElement = document.createElement('span');
    currentValueElement.innerHTML = `
      <strong>x </strong>
      <span class="value" id="${AUDIO_CURRENT_PLAYBACK_RATE_HTML_ID}">${this.player.playbackRate()}</span>
    `;

    const audioPlaybackMenuItemElement = document.createElement('li');
    audioPlaybackMenuItemElement.classList.add('vjs-audio-playback-rate-wrapper');
    audioPlaybackMenuItemElement.appendChild(buttonMinusElement);
    audioPlaybackMenuItemElement.appendChild(currentValueElement);
    audioPlaybackMenuItemElement.appendChild(buttonPlusElement);

    const AudioPlaybackMenuItem = new Component(this.player, {
      el: audioPlaybackMenuItemElement
    } as IAudioPlaybackMenuItemOptions);

    for (const child of AudioPlaybackRateButton.children()) {
      if (child.name() === AUDIO_PLAYBACK_RATE_BUTTON_NAME) {
        child.off('mouseenter');
      } else {
        child.addChild(AudioPlaybackMenuItem);
      }
    }

    this.player.getChild('ControlBar').addChild(AudioPlaybackRateButton);

    this.player.on('ratechange', () => {
      const playbackRate = this.player.playbackRate();
      const element = document.getElementById(AUDIO_CURRENT_PLAYBACK_RATE_HTML_ID);
      element.innerHTML = playbackRate;

      const MenuButton = AudioPlaybackRateButton.getChild(AUDIO_PLAYBACK_RATE_BUTTON_NAME);
      if (playbackRate !== RATE_NORMAL) {
        MenuButton.el().classList.add('active');
      } else {
        MenuButton.el().classList.remove('active');
      }
    });

    document.addEventListener('click', this.handleAudioPlaybackRateOutsideClick);
    window.addEventListener('blur', this.handleAudioPlaybackRateBlur);
  }

  private readonly handleAudioPlaybackRateOutsideClick = (event: MouseEvent) => {
    const relatedTarget = event.relatedTarget || document.activeElement;
    const AudioPlaybackRateButton = this.player.controlBar.getChild(AUDIO_PLAYBACK_RATE_BUTTON_NAME) as IMenuButton;
    const isChildTheTarget = AudioPlaybackRateButton.children().some(element => element.el() === relatedTarget);

    if (
      AudioPlaybackRateButton &&
      AudioPlaybackRateButton.buttonPressed_ &&
      !isChildTheTarget &&
      AudioPlaybackRateButton.el().firstChild !== relatedTarget
    ) {
      AudioPlaybackRateButton.unpressButton();
    }
  };
  private readonly handleAudioPlaybackRateBlur = () => {
    const AudioPlaybackRateButton = this.player.controlBar.getChild(AUDIO_PLAYBACK_RATE_BUTTON_NAME) as IMenuButton;

    if (AudioPlaybackRateButton && AudioPlaybackRateButton.buttonPressed_) {
      AudioPlaybackRateButton.unpressButton();
    }
  };
}
