







































































import { Component, Vue, Prop, Watch } from 'vue-property-decorator';
import { Statuses, SUPPORTED_LANGUAGES_LIST } from '@/types/constants';
import Video, { playerWrapper } from '@/components/styled/Video.js';
import Audio from '@/components/styled/Audio.js';
import StatusMessage from '@/components/styled/StatusMessage.js';
import socket from '@/utils/socket';
import { extractPlayerOptions } from '@/utils/queryStringParser';
import VJSPlayer from '@/player/player';
import { IMediaConfig, ITooltip } from '@/types/types';
import { ExtendedPlayer } from '@/types/player';
import { notifyStatusToParent } from '@/utils/utils';
import Spinner from '@/components/Spinner.vue';
import Tooltip from '@/components/Tooltip.vue';
import clientConfig from '@/config';

const FORCE_PLAYER_MESSAGE = 'FORCE_PLAYER';

@Component({
  components: {
    'styled-video': Video,
    'styled-audio': Audio,
    'player-wrapper': playerWrapper,
    StatusMessage,
    Spinner,
    Tooltip
  }
})
export default class Player extends Vue {
  @Prop() mediaFileInfo: any;
  @Prop() isOffline: boolean;
  queryStringOptions: any = extractPlayerOptions(window.location.search);
  player = new VJSPlayer(this.queryStringOptions, this.$t);
  status = Statuses.Available;
  allStatuses = Statuses;
  $refs!: {
    easyPlayer: HTMLFormElement;
    tooltip: Vue & ITooltip;
  };
  initialize({ thumbnail, sources, subtitles }: IMediaConfig) {
    this.player.setPoster(thumbnail);
    this.player.setSources(sources);

    if (subtitles && subtitles.length) {
      this.player.setSubtitles(subtitles);
    }

    if (
      this.queryStringOptions.lang &&
      SUPPORTED_LANGUAGES_LIST.find(lang => lang.code === this.queryStringOptions.lang)
    ) {
      this.player.setQueryStringLang(this.queryStringOptions.lang);
    }

    if (this.queryStringOptions.subLang) {
      this.player.setPreferredSubtitleLang(this.queryStringOptions.subLang);
    }

    this.player.initialize(this.$refs.easyPlayer.$el, this.$refs.tooltip);
  }

  connectToSockets(sourceId: string) {
    socket.connect();
    socket.emit('init-public', sourceId);
    const statusChangedEvent = this.player.options.video ? 'video-public-info-changed' : 'audio-public-info-changed';
    socket.on(statusChangedEvent, this.onStatusChanged);
  }

  mounted() {
    this.status = this.mediaFileInfo.status;
    switch (this.status) {
      case Statuses.Uploading:
      case Statuses.Converting:
      case Statuses.Loaded:
        this.connectToSockets(this.mediaFileInfo.sourceId);
        break;
      case Statuses.Available:
        this.initialize(this.mediaFileInfo);
        break;
    }

    window.addEventListener('message', this.handleMessageEvent);
  }

  beforeDestroy() {
    this.player.dispose();
    window.removeEventListener('message', this.handleMessageEvent);
  }

  private handleMessageEvent(event: MessageEvent) {
    const parentUrl = clientConfig.parentOrigin;

    if (parentUrl && event.origin !== parentUrl) {
      return;
    }

    if (event.data !== FORCE_PLAYER_MESSAGE || this.status !== Statuses.Available) {
      return;
    }

    const playerInstance = (this.player as unknown as { player: ExtendedPlayer }).player;

    if (playerInstance && !this.player.options.video && playerInstance.paused()) {
      playerInstance.play();
    }
  }

  @Watch('player.shouldRerender')
  onReRender() {
    this.$emit('rerender');
  }

  private onStatusChanged(data: any) {
    this.status = data.status;
    notifyStatusToParent(data.status);
    if (data.status === Statuses.Available) {
      this.initialize(data);
      socket.disconnect();
    }
  }

  get isVideoUnderProcessing() {
    return (
      this.status === this.allStatuses.Uploading ||
      this.status === this.allStatuses.Loaded ||
      this.status === this.allStatuses.Converting
    );
  }
}
