import { Statuses } from './constants';

type Status = (typeof Statuses)[keyof typeof Statuses];

export enum MediaType {
  Video = 'video',
  Audio = 'audio'
}

export interface MediaInfoConfig {
  isVideo: boolean;
  source: string;
  thumbnail?: string;
  isOffline?: boolean;
  courseId?: string;
  publishMode?: string;
}

export interface MediaSource {
  src: string;
  type: string;
}

export interface MediaFileInfo {
  status: Status;
  sources: MediaSource[];
  thumbnail?: string;
  [key: string]: unknown;
  isPortrait?: boolean;
}
