export const progressHolder = colors => `
  .vjs-progress-holder {
    height: 0.2em;
    background-color: ${hexToRgba(colors[mainColor], 0.3)};
    filter: saturate(90%);
    margin: 0;

    .vjs-load-progress {
      background-color: ${hexToRgba(colors[mainColor], 0.5)};
      filter: saturate(90%);
      height: 100%;
      border-radius: 0.3em;

      div {
        background-color: transparent;
        height: 100%;
        border-radius: 0.3em;
      }
    }

    .vjs-play-progress {
      background-color: ${colors[mainColor]};
      border-radius: 0.3em;
      height: 100%;

      &:before {
        opacity: 0;
        content: '';
        display: block;
        border-radius: 50%;
        width: 12px;
        height: 12px;
        background-color: ${colors[mainColor]};
        top: 50%;
        right: calc(-12px / 2);
        margin-top: calc(-12px / 2);
        transition: 0.2s;
      }

      &:focus:before {
        outline: 2px solid black !important;
      }

      &:after {
        font-family: sans-serif;
      }
    }

    .vjs-mouse-display {
      font-family: sans-serif;
    }

    ${
      colors[designType] === 1
        ? `
        .vjs-play-progress {
          background: ${colors[mainColor]};
          transition: background 0.1s linear;

          &:before {
            top: 5px;
            right: -2px;
            width: 4px;
            height: 4px;
            opacity: 1;

            background: ${colors[contentBodyColor]};
            box-shadow: 0 0 0 5px ${colors[mainColor]};
          }

          &:after {
            display: none;
          }
        }

        .vjs-load-progress {
          background-color: transparent;

          div {
            background-color: ${hexToRgba(colors[mainColor], 0.2)};
            filter: brightness(1.3);
          }
        }
      `
        : ''
    }
  }
`;

